Certainly! One of the most common path search algorithms is the **A* (A-star) algorithm**, which is often used for pathfinding and graph traversal. The A* algorithm is particularly efficient and guarantees to find the shortest path when using an appropriate cost function.

Here's a Python implementation of the A* algorithm:

```python
import heapq

def heuristic(a, b):
    # Heuristic function (Manhattan distance in 2D space)
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def a_star_search(graph, start, goal):
    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return path[::-1]  # Return reversed path

        for neighbor, cost in graph[current].items():
            tentative_g_score = g_score[current] + cost

            if tentative_g_score < g_score.get(neighbor, float('inf')):
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return None  # No path found

# Example usage:

# Define the graph as a dictionary where keys are nodes and values are a dictionary of
# neighboring nodes and their costs to reach them.
graph = {
    'A': {'B': 1, 'C': 4},
    'B': {'A': 1, 'C': 2, 'D': 5},
    'C': {'A': 4, 'B': 2, 'D': 1},
    'D': {'B': 5, 'C': 1}
}

start_node = 'A'
goal_node = 'D'
path = a_star_search(graph, start_node, goal_node)
print("Path found:", path)
```

