Certainly! Let's implement a simple path search algorithm such as Breadth-First Search (BFS) to find a path between two nodes in an unweighted grid graph. BFS is a graph traversal algorithm that explores all the vertices of a graph in breadth-first order, i.e., it goes as far as possible along each level of the graph before moving to the next level.

Here’s a Python implementation of BFS to find a path between two nodes in a grid graph:

```python
from collections import deque

def is_valid(x, y, grid):
    """Check if the coordinates are within the grid bounds."""
    return 0 <= x < len(grid) and 0 <= y < len(grid[0])

def bfs(grid, start, goal):
    """Breadth-First Search algorithm to find a path in a grid."""
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # Right, Down, Up, Left
    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        (x, y), path = queue.popleft()

        if (x, y) == goal:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny, grid) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), path + [(nx, ny)]))

    return None

def print_path(grid, path):
    """Print the grid with the path highlighted."""
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i, j) in path:
                print("X", end=" ")
            else:
                print(grid[i][j], end=" ")
        print()
    print()

# Example usage
if __name__ == "__main__":
    grid = [
        ['S', 'X', 'X', 'X', 'X'],
        ['X', 'G', 'X', 'X', 'X'],
        ['X', 'X', 'X', 'X', 'X'],
        ['X', 'X', 'X', 'X', 'X'],
        ['X', 'X', 'X', 'X', 'X']
    ]

    start = (0, 0)  # Starting point
    goal = (4, 4)   # Goal point

    path = bfs(grid, start, goal)

    if path:
        print("Path found:")
        print_path(grid, path)
    else:
        print("No path found.")
